"""Form Three Français intensif, Term One. Prescribed literature and ambiguous rows remain pending."""
from codex_support import *
from lessonlib import mcq
import banks_fr as B
F=fact

def unit(n,title,note,case,method,facts,**kw):
    concept_lesson("francais-intensif","fi3-",n,title,note,case,method,facts,"francais",language="fr",**kw)

def vocab(n,title,note,case,rows,method=None):
    unit(n,title,note,case,method or "Lis la phrase entière, relève les indices et compare les sens. Choisis un mot pour ce contexte, puis emploie-le dans une phrase originale. Un exemple n’autorise pas une généralisation à toutes les situations. Explique ton choix sans recopier une définition sans rapport.",[F(*r) for r in rows])

vocab(1,"Les antonymes",
 "Les antonymes expriment des sens opposés sur un même aspect. Pour trouver un contraire, identifie le sens exact du mot dans la phrase. Une porte ouverte s’oppose à une porte fermée ; une personne ouverte peut demander une autre opposition. Certains contraires prennent un préfixe, d’autres sont des mots différents. Une simple ressemblance de lettres ou de son ne crée pas une opposition.",
 "Dans une classe fictive de Buea, Bih compare une boîte pleine et une boîte vide, une porte ouverte et une porte fermée. Elle oppose ensuite un passage large à un passage étroit. Chaque paire conserve le même objet ou le même axe de comparaison.",[
 ("vide","contraire de plein pour un récipient sans contenu","La boîte ne contient rien : elle est vide.","Vide signifie rempli jusqu’au bord.","L’opposition porte ici sur la présence de contenu."),("fermé","contraire d’ouvert pour une porte","La porte n’est plus ouverte : elle est fermée.","Fermé est toujours synonyme d’ouvert.","Ce sont ici deux états opposés."),("étroit","contraire de large pour un passage","Le passage de faible largeur est étroit.","Étroit et large expriment toujours la même largeur.","Ils s’opposent sur la largeur."),("impoli","contraire de poli pour un comportement","Une réponse irrespectueuse est impolie.","On forme tous les antonymes avec le seul préfixe im-.","Les contraires se forment de plusieurs façons.")])

unit(2,"Les présentatifs : voici et voilà",
 "Voici et voilà servent à présenter ou à montrer une personne, un objet ou une information. Dans un contraste spatial simple, voici présente ce qui est proche du locuteur et voilà ce qui est plus éloigné. Ce n’est pas leur seul emploi : ils peuvent aussi organiser un discours ou reprendre une information. Ces formes restent invariables devant un nom singulier ou pluriel. Elles ne sont pas des déterminants possessifs.",
 "Dans le modèle spatial, Bih tient un cahier et dit : « Voici mon cahier. » Elle montre plus loin une affiche : « Voilà l’affiche du club. » Elle peut présenter plusieurs livres sans ajouter de marque de pluriel à voici. Dans un exposé, voici le projet annonce aussi une information à expliquer.",
 "Demande-toi si le mot présente quelque chose et si le contexte impose une opposition proche/éloigné. Ne transforme pas une préférence de présentation en interdiction de tout autre emploi standard. Observe le nom après le présentatif sans accorder voici ou voilà.",[
 F("voici","le présentatif du proche dans le contraste spatial étudié","Bih tient le cahier : voici mon cahier.","Voici doit toujours prendre un s devant plusieurs objets.","Le présentatif reste invariable."),F("voilà","le présentatif de l’éloigné dans le contraste spatial étudié","Bih montre l’affiche plus loin : voilà l’affiche.","Voilà ne peut présenter que des noms singuliers.","On peut présenter plusieurs objets avec le même mot."),F("présentation d’information","l’emploi d’un présentatif pour introduire un contenu","Voici le projet annonce ce qui va être expliqué.","Un présentatif ne peut jamais organiser le discours.","Son emploi dépasse le seul contraste de distance."),F("invariabilité","l’absence de variation du présentatif selon le nom","Voici des livres conserve la même forme de voici.","Le pluriel exige obligatoirement voicis.","Voici ne reçoit pas le pluriel du nom.")])

unit(4,"Préparer un chant : sens et articulation",
 "Un chant associe un texte, un rythme et une mélodie. La préparation écrite aide à comprendre les paroles et à repérer des groupes de sens. Elle ne permet pas d’entendre une hauteur musicale ni de vérifier la justesse. Cette leçon utilise un texte original sans partition ; le chant réel doit être travaillé avec un enseignant ou un modèle sonore adapté. Un élève ne doit pas deviner une mélodie à partir de la seule ponctuation.",
 "Paroles originales de préparation : « Dans notre cour, chacun prend place ; une voix répond à la voix. Nous partageons le même espace, et nous écoutons chaque fois. » Le texte évoque l’écoute et la vie commune. On peut expliquer son sens avant de le mettre en musique avec un modèle choisi par l’enseignant.",
 "Repère les idées, les retours de mots et les limites des groupes de sens. Prépare une articulation compréhensible sans crier. Distingue ce que la page montre de ce que seul un modèle sonore peut fournir. La pratique de la mélodie reste une activité de classe.",[
 F("paroles","le texte verbal d’un chant","Le lecteur explique le message de Dans notre cour.","Les paroles sont uniquement les hauteurs musicales.","Les paroles sont les mots, distincts de la mélodie."),F("rythme","l’organisation des durées et des accents dans la réalisation","L’enseignant propose une façon régulière d’enchaîner les paroles.","La durée des syllabes se lit toujours exactement dans les lettres seules.","Le texte seul ne fixe pas toutes les durées d’un chant."),F("mélodie","l’enchaînement des hauteurs musicales","Un modèle sonore indique la succession des notes.","Une page sans partition évalue à elle seule la justesse de la voix.","Il faut un modèle sonore ou musical pour travailler la mélodie."),F("articulation","la réalisation distincte des sons des mots","Le groupe prépare des mots compréhensibles sans crier.","Articuler consiste à avaler toutes les syllabes.","L’articulation vise à rendre les mots distincts.")])

def present(n,title,verbs,note,case,facts):
    unit(n,title,note,case,
      "Trouve l’infinitif et le sujet. Choisis la base et la terminaison propres à ce verbe, puis relis le groupe complet. Une terminaison d’un autre sujet ne convient pas uniquement parce qu’elle se prononce de façon proche. Les modèles sont calculés par les bibliothèques de conjugaison.",facts,
      replacement={2:mcq(f"fi3-{n}-conjuguer",2,"Conjugue « {v} » au présent avec « {fr2Pronoun(p)} ».","{fr2With(p,fr2Present(v,p))}",[("{fr2With(p,fr2Present(v,(p+1)%8))}","personne"),("{fr2With(p,fr2Present(v,(p+4)%8))}","autre"),("{fr2With(p,v)}","infinitif")],["Repère le sujet {fr2Pronoun(p)} et le verbe {v}.","La forme au présent est {answer}."],vars={"v":{"pick":verbs},"p":{"int":[0,7]}},where=["fr2Present(v,p) != fr2Present(v,(p+1)%8)","fr2Present(v,p) != fr2Present(v,(p+4)%8)","fr2Present(v,(p+1)%8) != fr2Present(v,(p+4)%8)"],misc=[("personne","Cette terminaison appartient à un autre sujet ; garde la personne demandée."),("autre","Tu as appliqué la forme d’une autre personne grammaticale."),("infinitif","Tu as conservé l’infinitif au lieu de conjuguer le verbe.")],sources=["francais"],lang="fr")})

present(6,"Le présent des verbes du premier groupe",["parler","travailler","jouer","aider"],
 "Les verbes réguliers du premier groupe ont un infinitif en -er et des terminaisons de présent -e, -es, -e, -ons, -ez, -ent. Aller se termine aussi en -er mais appartient au troisième groupe. Le radical porte l’idée du verbe ; la terminaison varie avec le sujet. Le présent peut décrire une action actuelle ou une habitude. Le titre du spine est incomplet : cette leçon traite clairement le premier groupe, le deuxième étant étudié plus loin.",
 "Avec parler, compare {fr2With(0,fr2Present('parler',0))}, {fr2With(1,fr2Present('parler',1))}, {fr2With(4,fr2Present('parler',4))} et {fr2With(6,fr2Present('parler',6))}. Certaines formes ont une prononciation proche mais des écritures différentes. Le sujet décide de la terminaison.",[
 F("infinitif","la forme qui nomme le verbe avant sa conjugaison","Parler est le verbe nommé à l’infinitif.","Parler est obligatoirement une forme conjuguée avec nous.","L’infinitif ne porte pas ici la terminaison personnelle de nous."),F("radical","la base conservant l’idée du verbe régulier étudié","Le radical parl- apparaît dans {fr2Present('parler',4)}.","La base de parler est obligatoirement finiss-.","Finiss- appartient à un autre verbe."),F("terminaison personnelle","la finale choisie selon le sujet","Avec vous, on obtient {fr2Present('parler',5)}.","Vous au présent de parler exige -ons.","Vous prend -ez dans ce modèle."),F("exception aller","le cas d’un verbe en -er qui ne relève pas du premier groupe","Aller appartient au troisième groupe.","Tous les verbes en -er appartiennent sans exception au premier groupe.","Aller est une exception à cette généralisation.")])

for n,title,case in [(7,"Préparer la mélodie d’une déclarative affirmative","Phrase modèle : Bih prépare le cahier. Elle donne une information affirmative. Dans une réalisation neutre isolée, la fin peut être descendante, mais l’intention et le contexte modifient l’intonation. La page ne permet pas de l’entendre."),(15,"Préparer la mélodie d’une déclarative négative","Phrase modèle : Bih ne prépare pas le cahier. La négation change le contenu, mais ne transforme pas automatiquement la phrase en question. Dans une réalisation neutre isolée, la fin peut être descendante ; l’intonation réelle doit être entendue et pratiquée."),(50,"Préparer la mélodie d’une phrase impérative","Phrase modèle : {fr2Imperatif('écouter',1)} la consigne. Le verbe {fr2Imperatif('écouter',1)} invite le groupe à agir. Le ton peut exprimer une demande calme ou une consigne ferme selon le contexte. Un ordre ne doit pas être automatiquement crié ; la voix ne peut pas être évaluée sur cette page.")]:
    unit(n,title,"L’intonation organise la voix et contribue à l’intention. La structure grammaticale et la ponctuation donnent des indices, mais elles ne fixent pas chaque mouvement de hauteur. Une phrase peut être informative, expressive ou contrastive selon le contexte. Cette leçon prépare la lecture écrite et les groupes de sens ; elle ne teste ni l’écoute ni la prononciation. Une réalisation sonore guidée par l’enseignant reste nécessaire.",case,
      "Identifie d’abord la structure et le sens. Marque les groupes de sens sur le texte, puis explique l’intention sans inventer un son que tu n’as pas entendu. Compare ensuite des réalisations avec l’enseignant. Ne confonds pas négation et interrogation, ni impératif et cri.",[
      F("structure grammaticale","l’organisation des mots indépendamment d’une réalisation particulière de la voix","Une négation peut rester dans une phrase déclarative.","La présence de ne transforme toujours la phrase en question.","La négation et le type interrogatif sont deux analyses distinctes."),F("intonation","l’évolution de la hauteur de la voix dans l’énoncé","Un modèle sonore permet de comparer une fin montante et une fin descendante.","Une page muette permet d’entendre réellement la voix.","Le texte prépare ; un modèle sonore fournit le son."),F("groupe de sens","une unité de mots à garder compréhensible dans la diction","Le lecteur prépare une séparation après une idée complète.","Couper chaque mot au milieu facilite toujours le sens.","Les coupures doivent respecter les unités de sens."),F("intention du locuteur","le but de la prise de parole dans son contexte","La même structure peut être dite calmement pour informer.","Toutes les phrases impératives doivent obligatoirement être criées.","La force et la hauteur dépendent du contexte et de l’intention.")])

for n,title,pairs in [(8,"Graphies du son /o/",[("eau","eau"),("bateau","eau"),("chaud","au"),("rose","o")]),(20,"Distinguer les modèles écrits /o/ et /ɔ/",[("eau","/o/"),("rose","/o/"),("porte","/ɔ/"),("sol","/ɔ/")]),(29,"Préparer les voyelles nasales /ɛ̃/ et /œ̃/",[("pain","/ɛ̃/"),("matin","/ɛ̃/"),("un","/œ̃/"),("parfum","/œ̃/")])]:
    unit(n,title,"Une graphie est une façon d’écrire ; un symbole phonétique représente un son dans un modèle de prononciation. Plusieurs graphies peuvent représenter un même son et une graphie peut varier selon le mot. Les exemples servent à une observation écrite. Certains accents ne distinguent pas toutes les voyelles de la même manière, notamment /ɛ̃/ et /œ̃/. L’enseignant doit confirmer le modèle de la classe et fournir une pratique sonore ; aucun test d’écoute n’a lieu ici.",
      "Modèles à observer : "+" ; ".join(w+" → "+s for w,s in pairs)+". Compare le mot entier et son groupe plutôt que de généraliser une seule lettre à tous les mots. Dans une voyelle nasale, la notation ne signifie pas nécessairement qu’il faut prononcer une consonne n séparée après la voyelle.",
      "Repère la graphie dans le modèle, compare la notation puis classe les exemples écrits. Vérifie les mots nouveaux dans un dictionnaire ou avec l’enseignant. La reconnaissance d’un mot écrit ne prouve pas la bonne réalisation de sa voyelle.",[
      F(w,"le modèle écrit « "+w+" » associé ici à « "+s+" »",w+" est associé au groupe "+s+" dans le modèle.","Le modèle "+w+" autorise à appliquer sa graphie à tous les autres mots.","Apprends le modèle et vérifie les mots nouveaux au lieu de généraliser sans contrôle.") for w,s in pairs])

def writing(n,title,note,model,method,facts,prompt,checks):
    unit(n,title,note,"Modèle original : "+model,method,facts,paper=paper(prompt,[model],checks))

writing(10,"Décrire une chambre imaginaire",
 "Une description de lieu guide le regard. Présente le lieu puis organise les détails, par exemple de l’entrée vers le fond. Les repères à gauche, près de et en face de indiquent les positions. Choisis les objets utiles à l’impression recherchée et vérifie les accords. Tu peux inventer la chambre : l’exercice ne demande ni l’adresse ni une description privée de ton domicile.",
 "Dans une chambre imaginaire de Buea, une petite table se trouve près de la fenêtre. Le lit occupe le côté opposé. Une étagère garde les livres à portée de main et le passage reste dégagé. L’ordre de la description permet de se représenter la pièce sans accumuler des objets sans lien.",
 "Choisis un point de départ, un parcours et une impression générale. Utilise des repères cohérents plutôt que ici et là sans référence. Vérifie que la position d’un objet ne change pas accidentellement entre les phrases.",[
 F("présentation du lieu","l’indication de la pièce que l’on décrit","Le texte annonce une chambre imaginaire.","Le lecteur doit obligatoirement deviner le lieu sans indice.","Présente assez clairement le lieu décrit."),F("repère spatial","une expression situant un objet par rapport à un autre","Près de la fenêtre situe la table.","Près de indique toujours une date.","L’expression indique ici une position."),F("parcours descriptif","un ordre guidant le regard dans le lieu","Le texte va de l’ouverture aux meubles opposés.","Changer d’endroit au hasard garantit une description claire.","Un parcours cohérent aide à se représenter l’espace."),F("impression générale","l’effet d’ensemble soutenu par les détails choisis","Le passage dégagé soutient l’idée d’un espace organisé.","Une impression ne doit avoir aucun lien avec les détails.","Les détails doivent soutenir l’effet annoncé.")],
 "Décris une chambre entièrement imaginaire. Guide le regard avec des repères et conserve des positions cohérentes.",["Je présente le lieu sans données privées.","Mes repères permettent de situer les objets.","Je vérifie l’ordre des détails et les accords."])

vocab(11,"Les synonymes",
 "Des synonymes ont des sens proches dans un contexte. Ils peuvent différer par le registre, l’intensité ou leur construction. Vérifie la phrase entière avant de remplacer un mot. La synonymie n’est ni une identité parfaite dans tous les emplois, ni une ressemblance sonore. Conserve l’idée principale et une construction grammaticale correcte.",
 "Bih décrit une ambiance calme, donc paisible dans ce contexte. Elle est contente, ou heureuse, de retrouver son amie. Une vaste étendue est grande. Une tâche ardue est difficile. Ces équivalents doivent rester adaptés au nom et à l’intention de la phrase.",[
 ("paisible","proche de calme pour une ambiance sans agitation","La cour calme offre une ambiance paisible.","Paisible signifie toujours agitée.","Paisible exprime ici l’absence d’agitation."),("heureux","proche de content dans un contexte de satisfaction","Le personnage content de retrouver son amie en est heureux.","Heureux est nécessairement le contraire de content.","Ces mots expriment ici des sentiments proches."),("vaste","proche de grand pour une étendue","Une grande étendue est qualifiée de vaste.","Vaste peut remplacer grand dans absolument toutes les expressions.","La substitution dépend du sens et des mots voisins."),("ardue","proche de difficile pour une tâche exigeante","La tâche difficile peut être dite ardue.","Ardue signifie sans effort dans ce modèle.","Une tâche ardue exige un effort.")])

unit(12,"Le présentatif c’est",
 "C’est permet notamment d’identifier ou de caractériser ce que l’on présente. C’ vient de ce et est est une forme du verbe être. Ne confonds pas c’est avec s’est, qui appartient à une construction pronominale au passé composé. Pour présenter un nom pluriel dans le modèle scolaire formel, on emploie ce sont. Des usages oraux sont plus souples ; le modèle donne la construction attendue dans l’exercice, sans nier les variations de la langue.",
 "Bih montre un cahier : « C’{fr2Present('être',2)} le cahier du club. » Devant plusieurs cahiers, le modèle formel donne : « Ce {fr2Present('être',6)} les cahiers du club. » Dans ce contexte, le présentatif identifie un objet. L’apostrophe relie c’ à est ; elle ne transforme pas ce mot en un possessif.",
 "Demande si la phrase présente ou identifie quelque chose. Vérifie ensuite la forme d’être et l’orthographe c’est. Ne remplace pas c’est par s’est uniquement parce que les deux se prononcent de façon proche.",[
 F("identification","la présentation de ce que désigne un élément","C’est le cahier du club identifie l’objet montré.","Identifier un objet consiste toujours à raconter un événement futur.","Le présentatif sert ici à dire de quel objet il s’agit."),F("c’","la forme élidée de ce dans c’est","L’apostrophe de c’est suit la lettre c.","Le c de c’est est obligatoirement le pronom réfléchi se.","C’ représente ici ce, pas se."),F("est","la forme d’être présente dans c’est","Dans c’est, être apparaît sous la forme {fr2Present('être',2)}.","Est est l’infinitif du verbe avoir.","Est est une forme d’être, pas d’avoir."),F("ce sont","le présentatif formel du modèle devant un groupe nominal pluriel","Ce {fr2Present('être',6)} les cahiers présente plusieurs objets.","Le modèle scolaire exige toujours ce est les cahiers.","Ce sont convient au groupe pluriel dans ce modèle formel.")])

present(13,"Le présent des verbes du deuxième groupe",["finir","choisir","grandir","réussir"],
 "Les verbes du deuxième groupe ont un infinitif en -ir et un participe présent en -issant. Au présent, finir donne -is, -is, -it, -issons, -issez, -issent. Tous les verbes en -ir ne suivent pas ce modèle : partir appartient au troisième groupe. La base en -iss- apparaît aux personnes du pluriel dans le modèle étudié. Il faut reconnaître le groupe avant de choisir la terminaison.",
 "Compare {fr2With(0,fr2Present('finir',0))}, {fr2With(4,fr2Present('finir',4))} et {fr2With(6,fr2Present('finir',6))}. Le même modèle s’applique à choisir. En revanche, partir ne prend pas mécaniquement la base partiss- au présent : une finale d’infinitif ne suffit pas à déterminer tout le groupe.",[
 F("infinitif en -ir","une caractéristique nécessaire mais non suffisante du deuxième groupe","Finir et partir ont la même finale d’infinitif sans suivre le même groupe.","Tout verbe en -ir appartient au deuxième groupe.","Le participe en -issant et le modèle permettent de distinguer les groupes."),F("participe en -issant","un critère du modèle du deuxième groupe","Finir donne {fr2ParticipePresent('finir')}.","Finir a pour participe présent finant.","La base du modèle comporte -iss-."),F("base du pluriel","la forme en -iss- utilisée aux personnes plurielles du modèle","Nous donne {fr2Present('choisir',4)}.","Nous au présent de choisir se forme sans -iss-.","Choisir suit ici le modèle choisissons."),F("troisième groupe","la catégorie de partir, qui ne suit pas le modèle finir","Partir donne {fr2Present('partir',4)} avec nous.","Partir doit donner partissons avec nous.","Partir suit un autre modèle.")])

writing(16,"Raconter une journée",
 "Raconter sa journée demande de sélectionner des activités et de les ordonner. Les repères le matin, ensuite et le soir aident le lecteur. Choisis un temps cohérent avec le projet : une journée habituelle et une journée achevée ne sont pas présentées de la même manière. Une liste sans lien donne moins de sens qu’un récit organisé. Tu peux raconter la journée d’un personnage imaginaire.",
 "Le matin, un personnage imaginaire prépare son sac puis rejoint sa classe. Après les cours, il aide à ranger du matériel avant de relire ses notes. Le soir, il prépare le travail du lendemain. Le texte présente une journée habituelle au présent et relie les activités sans dévoiler une adresse personnelle.",
 "Prépare les moments utiles, choisis le point de vue et le temps, puis relie les actions. Ajoute une précision pertinente plutôt que toutes les minutes de la journée. Relis les pronoms pour que le lecteur sache toujours qui agit.",[
 F("chronologie","l’ordre temporel des activités","Le matin précède le soir dans le récit linéaire.","La chronologie signifie un classement des objets par couleur.","Elle concerne l’ordre dans le temps."),F("repère temporel","une expression situant l’action dans la journée","Après les cours situe une activité.","Après les cours indique toujours une couleur.","L’expression donne un moment relatif."),F("cohérence des temps","le choix de formes compatibles avec le récit voulu","Une journée habituelle peut être présentée au présent.","On change de temps à chaque phrase sans aucun motif.","Les changements doivent avoir une justification dans le récit."),F("sélection des faits","le choix d’activités utiles au récit","Le personnage garde les actions qui font comprendre sa journée.","Une narration exige tous les détails privés sans exception.","Sélectionne les faits pertinents et protège la vie privée.")],
 "Raconte la journée habituelle d’un personnage imaginaire. Utilise un point de vue et des repères cohérents.",["Les activités suivent un ordre lisible.","Mes temps et pronoms restent cohérents.","Je choisis des détails utiles sans données privées."])

unit(17,"Pronoms personnels COI : formes et fonctions",
 "Un complément indirect est lié au verbe par sa construction, souvent avec une préposition dans le groupe développé. Devant le verbe, les formes conjointes étudiées sont me, te, lui, nous, vous, leur. Après une préposition conservée, on emploie notamment moi, toi, lui, elle, nous, vous, eux, elles. Le titre du spine mêle ces séries : il faut les distinguer. Lui et leur conjoints remplacent des personnes selon la construction ; ils ne portent pas le genre comme elle ou elles.",
 "Bih parle à Ayuk : Bih lui parle. Elle parle à ses camarades : elle leur parle. Pour insister avec certains verbes ou conserver une préposition, la construction diffère : elle pense à lui. On ne remplace donc pas automatiquement toute suite à + personne par le même pronom devant n’importe quel verbe.",
 "Identifie le verbe, sa construction et la place du pronom. Distingue personne unique et groupe. Vérifie si la préposition reste présente ; n’écris pas elle leur parle comme s’il s’agissait de leur cahier, où leur est un déterminant.",[
 F("lui conjoint","le pronom COI du modèle remplaçant à une personne devant parler","Bih parle à Ayuk devient Bih lui parle.","Lui devant parle signifie toujours un groupe de plusieurs destinataires.","Dans ce modèle, lui remplace une personne unique."),F("leur conjoint","le pronom COI du modèle remplaçant à plusieurs personnes devant parler","Bih parle à ses camarades devient Bih leur parle.","Le pronom leur devant le verbe prend toujours un s.","Le pronom COI leur reste invariable."),F("forme disjointe","une forme telle que moi ou toi après une préposition conservée","Le groupe avec moi emploie une forme disjointe.","Après avec, on écrit obligatoirement avec me.","Après cette préposition, la forme attendue est moi."),F("construction verbale","la manière dont le verbe introduit son complément","Penser à lui conserve à dans le modèle.","Tous les verbes construisent leur complément exactement comme parler.","La pronominalisation dépend de la construction du verbe.")])

present(18,"Le présent des verbes du troisième groupe",["aller","faire","prendre","venir","lire"],
 "Le troisième groupe rassemble des verbes de modèles variés. Il ne possède pas une seule série de terminaisons qui fonctionnerait pour tous. Apprends les formes par familles et par personnes : aller, faire, prendre, venir et lire ne gardent pas tous le même radical. Une irrégularité n’autorise pas à deviner n’importe quelle forme. Les verbes choisis sont présents dans la bibliothèque de conjugaison de l’application.",
 "Compare {fr2With(0,fr2Present('aller',0))} et {fr2With(4,fr2Present('aller',4))} ; puis {fr2With(0,fr2Present('prendre',0))} et {fr2With(4,fr2Present('prendre',4))}. La variation touche la base et la terminaison. Reconnaître le sujet reste nécessaire même lorsqu’on connaît le sens du verbe.",[
 F("aller","le modèle illustré par vais et allons","Avec nous : {fr2Present('aller',4)}.","Aller se conjugue obligatoirement comme parler au présent.","Aller possède un modèle particulier."),F("faire","le modèle illustré par fais et faites","Avec vous : {fr2Present('faire',5)}.","Vous au présent de faire donne faisez.","La forme est particulière et se vérifie dans le modèle."),F("prendre","le modèle présentant pren- aux personnes concernées","Avec nous : {fr2Present('prendre',4)}.","Nous au présent de prendre donne prendons.","Le modèle utilise prenons."),F("venir","le modèle illustré par viens et venons","Avec nous : {fr2Present('venir',4)}.","Venir suit obligatoirement le même modèle que finir.","Venir ne forme pas venissons dans ce modèle.")])

vocab(21,"Le lexique de l’affection et du respect",
 "L’affection peut concerner la famille, l’amitié ou d’autres relations. L’amitié, la tendresse, le respect et la confiance ne sont pas des synonymes parfaits. On peut exprimer un sentiment sans exiger qu’une autre personne partage le même sentiment. Respecter une limite fait partie d’une relation attentive. Les exemples sont fictifs et adaptés à la classe ; l’exercice ne demande aucune confidence personnelle.",
 "Bih remercie une amie qui l’a écoutée. Ayuk exprime de l’affection envers sa famille. Un personnage demande la permission avant de partager une histoire privée. Ces actions permettent de discuter les mots sans transformer le sentiment en droit de contrôler quelqu’un.",[
 ("amitié","une relation d’attachement entre amis","Bih entretient un lien amical avec une camarade.","L’amitié donne le droit d’imposer toutes ses décisions à autrui.","Une relation amicale doit respecter les choix de l’autre."),("tendresse","une affection exprimée avec douceur","Un personnage adresse une parole douce à un proche.","La tendresse signifie nécessairement une menace.","Elle évoque ici une expression douce de l’affection."),("respect","la considération accordée à la dignité et aux limites d’autrui","Un personnage accepte qu’une amie garde une histoire privée.","Respecter quelqu’un oblige à divulguer sa vie privée.","Le respect inclut la prise en compte des limites."),("confiance","le fait de pouvoir compter sur une personne dans la relation décrite","Une amie garde une confidence comme convenu.","La confiance se renforce toujours en trahissant une confidence.","Tenir un engagement peut soutenir la confiance.")])

unit(22,"Pronoms personnels après une préposition",
 "Après une préposition conservée comme avec, pour ou chez, on emploie les formes disjointes moi, toi, lui, elle, nous, vous, eux, elles. Leur n’est pas la forme attendue dans avec eux. Attention : préposition et proposition sont deux termes différents ; la ligne du spine semble employer le second à la place du premier. La transformation dépend toujours du verbe : penser à lui ne se construit pas exactement comme lui parler.",
 "Bih travaille avec moi ; le livre reste chez elle ; Ayuk apporte un cahier pour eux ; un personnage pense à toi. Dans chaque modèle, le pronom suit une préposition présente à l’écrit. Le choix du pronom respecte la personne et le nombre du groupe remplacé.",
 "Repère la préposition, le référent et le nombre. Choisis la forme disjointe appropriée et relis le groupe entier. Ne remplace pas eux par leur après avec et ne transforme pas mécaniquement penser à elle en lui penser.",[
 F("moi","la forme disjointe de la personne qui parle","Le modèle écrit avec moi.","Après avec, la forme me remplace toujours moi.","Me est une forme conjointe ; ici on attend moi."),F("toi","la forme disjointe de la personne tutoyée","Le modèle écrit pour toi.","Pour te est un groupe complet équivalent à pour toi sans autre verbe.","Le groupe prépositionnel complet demande ici toi."),F("elle","la forme disjointe féminine singulière du modèle","Chez elle renvoie à une personne féminine singulière.","Chez elle désigne obligatoirement un groupe masculin pluriel.","Le référent étudié est féminin singulier."),F("eux","la forme disjointe masculine plurielle du modèle","Avec eux renvoie au groupe masculin ou mixte étudié.","Avec leur est la forme disjointe attendue pour ce groupe.","Après avec, on emploie ici eux, pas leur.")],replacement={2:B.QA("fi3-22-completer",2,"{X.q}",[
 dict(q="Complète : Bih travaille avec ___ (la personne qui parle).",r="moi",w=["me","je","mon"],e=["Me est une forme conjointe, pas la forme après avec.","Je est une forme sujet.","Mon est un déterminant possessif."],y="Après avec, la personne qui parle est représentée par moi."),
 dict(q="Complète : Le cahier est pour ___ (la personne tutoyée).",r="toi",w=["te","tu","ton"],e=["Te est une forme conjointe.","Tu est une forme sujet.","Ton accompagne un nom comme déterminant."],y="La forme disjointe attendue est toi."),
 dict(q="Complète : Bih vient avec ___ (le groupe masculin désigné).",r="eux",w=["leur","ils","les"],e=["Leur est ici une forme conjointe ou un déterminant, pas la forme après avec.","Ils est une forme sujet.","Les est une forme conjointe ou un article."],y="Avec conserve une forme disjointe : eux."),
 dict(q="Complète : Le livre reste chez ___ (Bih, personne féminine).",r="elle",w=["lui","la","elles"],e=["Lui disjoint est masculin dans ce groupe.","La ne forme pas ce groupe prépositionnel complet.","Elles changerait le nombre du référent."],y="Bih est ici le référent féminin singulier, donc elle.")],["francais"])})

writing(25,"Remplir une fiche de renseignements fictive",
 "Une fiche organise les informations dans des rubriques. Lis chaque intitulé avant d’écrire : nom, prénom, classe, activité ou contact de l’organisme n’attendent pas le même contenu. Une case vide et une réponse inventée ne signifient pas la même chose. Pour cet exercice, toutes les données sont fictives ; ne donne ni ton adresse réelle ni un numéro privé. Une fiche officielle peut avoir d’autres exigences que le modèle scolaire.",
 "FICHE FICTIVE DU CLUB. Nom : Personnage A. Prénom : Bih. Classe : Form Three. Activité choisie : lecture. Observation : exemple scolaire sans adresse ni téléphone réels. Chaque donnée répond à sa rubrique ; ce modèle ne sert à aucune inscription réelle.",
 "Repère les champs obligatoires dans la consigne, prépare des informations imaginaires cohérentes puis vérifie leur place. Écris lisiblement et ne déplace pas une réponse dans une rubrique sans rapport. Demande une clarification quand l’intitulé est ambigu.",[
 F("rubrique","un intitulé précisant l’information attendue","Activité choisie annonce le type de réponse à inscrire.","Une rubrique ne donne aucun indice sur la réponse attendue.","Elle précise justement la nature de l’information."),F("donnée fictive","une information inventée et signalée pour l’exercice","Personnage A évite de demander une identité réelle.","Une fiche de classe exige toujours une adresse privée réelle.","Cet exercice doit rester fictif."),F("cohérence","l’absence de contradictions entre les informations fournies","La classe et l’activité restent identiques dans toute la fiche.","Des réponses contradictoires rendent toujours la fiche plus claire.","Des données compatibles facilitent la compréhension."),F("vérification de champ","le contrôle qu’une réponse est placée dans la bonne rubrique","Le lecteur inscrit lecture dans activité, pas dans prénom.","On peut écrire n’importe quel contenu dans n’importe quelle case.","Chaque champ attend un type d’information précis.")],
 "Crée une fiche de club entièrement fictive avec nom de personnage, prénom imaginaire, classe et activité. N’utilise aucune adresse ni aucun téléphone réel.",["Je lis et complète chaque rubrique demandée.","Les réponses sont cohérentes et bien placées.","Toutes les données personnelles sont fictives."])

vocab(27,"Le lexique des maladies et des symptômes",
 "Un nom de maladie ne se confond pas avec un symptôme. Le paludisme est une maladie parasitaire transmise notamment par certains moustiques infectés ; la grippe est une infection respiratoire virale. La fièvre est un symptôme possible de plusieurs affections ; la diarrhée décrit l’émission de selles molles ou liquides plus fréquentes que d’habitude. Ces mots aident à comprendre un texte, mais un symptôme isolé ne permet pas à un élève de diagnostiquer quelqu’un. L’évaluation et les soins relèvent de professionnels compétents.",
 "Dans un dialogue fictif, Bih lit un document qui distingue nom de maladie et symptôme. Elle relève la fièvre sans conclure que la personne a nécessairement le paludisme. Un personnage demande un avis professionnel. Aucun médicament, dose ou traitement n’est prescrit dans l’exercice.",[
 ("paludisme","la maladie parasitaire transmise notamment par certains moustiques infectés","Un texte de santé associe cette maladie à un parasite et à des moustiques infectés.","Le paludisme est nécessairement causé par un manque de politesse.","Il s’agit d’une maladie parasitaire, pas d’un comportement moral."),("grippe","une infection respiratoire causée par des virus grippaux","Le document distingue une infection respiratoire virale de la maladie parasitaire.","La grippe est le nom de toutes les maladies sans exception.","Le mot désigne une infection particulière, pas toute maladie."),("fièvre","un symptôme d’élévation de la température corporelle","Le dialogue relève un symptôme thermique sans poser de diagnostic.","La fièvre prouve toujours à elle seule une maladie unique.","Plusieurs affections peuvent provoquer une fièvre."),("diarrhée","l’émission de selles molles ou liquides plus fréquentes que d’habitude","Le lecteur identifie ce terme dans un document sans choisir de traitement.","Le mot diarrhée désigne exclusivement une douleur du bras.","Le terme concerne les selles, pas une douleur du bras.")])

unit(28,"La négation : ne… pas, ne… plus et ne… jamais",
 "Dans l’écrit scolaire, ne et son second élément encadrent généralement le verbe conjugué à un temps simple. Ne… pas nie le fait ; ne… plus indique qu’il ne se poursuit pas ; ne… jamais indique l’absence à toute occasion dans le cadre décrit. Ne devient n’ devant une voyelle ou un h muet. Le mot jais du spine est interprété comme jamais, à confirmer. La disparition de ne dans certains usages oraux n’est pas le modèle écrit attendu ici.",
 "Compare Bih ne joue pas, Bih ne joue plus et Bih ne joue jamais dans les situations du modèle. La première phrase nie l’action, la deuxième évoque l’arrêt d’une pratique, la troisième son absence dans toutes les occasions visées. Ne choisis pas uniquement selon la longueur du mot : le sens change.",
 "Identifie d’abord ce que le locuteur nie : le fait, sa poursuite ou sa fréquence. Place ensuite les éléments autour du verbe au temps simple. Ne mets pas le second élément au hasard à l’intérieur du sujet.",[
 F("ne… pas","la négation simple du fait dans le modèle","Bih ne joue pas nie l’action dans le contexte.","Ne… pas signifie toujours que la personne jouait auparavant.","Le fait antérieur n’est pas nécessairement affirmé par cette négation."),F("ne… plus","la négation marquant la cessation dans le modèle","Bih ne joue plus indique l’arrêt de cette pratique.","Ne… plus signifie obligatoirement encore maintenant.","Plus négatif exprime ici la cessation."),F("ne… jamais","la négation de toute occasion dans le cadre décrit","Bih ne joue jamais exclut les occasions visées.","Jamais signifie toujours dans cette construction.","La négation exclut les occasions plutôt que de les inclure."),F("élision de ne","le passage de ne à n’ devant une voyelle ou un h muet","Le modèle n’aime pas commence par n’.","Ne ne peut jamais s’élider devant une voyelle.","L’élision donne n’ dans ce contexte.")],replacement={2:B.QA("fi3-28-choisir",2,"{X.q}",[
 dict(q="Bih jouait auparavant ; maintenant elle a arrêté. Quel énoncé correspond ?",r="Bih ne joue plus.",w=["Bih joue encore.","Bih a toujours joué sans arrêt.","Bih ne joue jamais depuis toujours."],e=["Encore maintient la pratique au lieu d’en signaler l’arrêt.","Cette phrase n’exprime pas la cessation actuelle.","Depuis toujours contredit le fait qu’elle jouait auparavant."],y="Ne… plus marque ici la cessation."),
 dict(q="Dans toutes les occasions décrites, Ayuk ne participe à aucune partie. Quel énoncé convient ?",r="Ayuk ne joue jamais.",w=["Ayuk joue toujours.","Ayuk joue parfois.","Ayuk joue encore."],e=["Toujours affirme l’inverse.","Parfois introduit des occasions que le cas exclut.","Encore n’exprime pas l’absence à toute occasion."],y="Jamais exclut les occasions du cadre décrit."),
 dict(q="On nie seulement que Bih joue en ce moment, sans information sur ses habitudes. Choisis la phrase la plus précise.",r="Bih ne joue pas maintenant.",w=["Bih ne joue plus depuis des années.","Bih ne joue jamais.","Bih joue maintenant."],e=["Cela ajoute un arrêt durable absent de la consigne.","Cela ajoute une généralisation sur les habitudes.","Cela affirme ce qu’il faut nier."],y="Ne… pas maintenant nie le fait présent sans ajouter d’histoire."),
 dict(q="Choisis la graphie écrite correcte de la négation avant aime.",r="Bih n’aime pas ce jeu.",w=["Bih ne aime pas ce jeu.","Bih aime ne ce jeu pas.","Bih n’aime ce jeu."],e=["Ne s’élide devant la voyelle.","Les éléments ne sont pas placés autour du verbe comme attendu.","Il manque le second élément pas dans le modèle écrit étudié."],y="Ne devient n’ devant aime et pas complète la négation.")],["francais"])})

vocab(32,"Le lexique des structures et services sanitaires",
 "Un hôpital est un établissement de soins ; un service d’urgences prend en charge des situations nécessitant une évaluation rapide ; les soins intensifs concernent une surveillance et des soins spécialisés ; une consultation est une rencontre professionnelle pour évaluer une situation de santé. Les services disponibles varient selon l’établissement. Ce vocabulaire n’indique pas à un élève comment trier ou traiter des patients et ne donne pas les coordonnées actuelles des services locaux.",
 "Dans une fiche fictive, un personnage distingue l’établissement, son service et le rendez-vous de consultation. Il demande au personnel compétent où se présenter. Le texte ne prétend pas que chaque centre possède tous les services et ne remplace pas les instructions d’un professionnel.",[
 ("hôpital","un établissement organisé pour des soins de santé","Le document nomme l’établissement où travaille une équipe de soins.","Un hôpital est obligatoirement une salle de classe sans soins.","Le terme désigne ici un établissement sanitaire."),("urgences","un service d’évaluation et de prise en charge de situations urgentes","La fiche distingue un service destiné aux situations nécessitant une évaluation rapide.","Urgences signifie que des élèves doivent décider seuls des priorités médicales.","Le tri et les soins relèvent du personnel compétent."),("soins intensifs","des soins et une surveillance spécialisés pour des patients qui en ont besoin","Le texte nomme une unité de surveillance spécialisée.","Tous les établissements possèdent forcément une unité de soins intensifs.","Les capacités varient ; vérifie l’établissement."),("consultation","une rencontre avec un professionnel pour évaluer une situation de santé","Un personnage se présente à un rendez-vous professionnel.","Une consultation signifie obligatoirement une opération chirurgicale.","L’évaluation ne se confond pas avec une intervention chirurgicale.")])

unit(33,"La phrase impérative",
 "L’impératif sert notamment à donner une consigne, faire une demande ou proposer une action commune. Il se construit sans pronom sujet exprimé. Les personnes usuelles correspondent à tu, nous et vous. Dans le modèle régulier en -er, la forme de tu ne garde pas le s du présent ; les contextes avec y ou en demandent une attention particulière non développée ici. Une phrase impérative peut rester polie et n’exige pas toujours un point d’exclamation.",
 "Avec travailler, les modèles sont {fr2Imperatif('travailler',0)}, {fr2Imperatif('travailler',1)} et {fr2Imperatif('travailler',2)}. Le modèle avec nous propose une action commune. Aucun pronom sujet ne précède ces formes. On peut ajouter s’il vous plaît à une demande selon la relation entre les personnes.",
 "Identifie le destinataire ou le groupe, choisis la forme puis retire le pronom sujet de la phrase impérative. Vérifie la négation si la consigne interdit une action. Ne confonds pas absence de sujet écrit et absence de destinataire.",[
 F("consigne","une instruction indiquant une action à réaliser","Range le matériel donne une instruction dans le modèle.","Une consigne ne peut jamais être exprimée poliment.","L’instruction peut conserver une forme courtoise."),F("absence de pronom sujet","la construction de l’impératif sans tu, nous ou vous exprimé comme sujet","{fr2Imperatif('travailler',2)} ne commence pas par vous sujet.","L’impératif exige toujours vous placé comme sujet avant le verbe.","Le sujet n’est pas exprimé ainsi dans le modèle."),F("action commune","la proposition impliquant le locuteur et le groupe","{fr2Imperatif('travailler',1)} invite le groupe à agir ensemble.","La forme de nous exclut toujours le locuteur.","Elle peut proposer une action à laquelle le locuteur participe."),F("forme singulière en -er","le modèle sans s de la personne correspondant à tu dans les cas étudiés","{fr2Imperatif('travailler',0)} ne garde pas le s du présent avec tu.","Tous les impératifs sans exception gardent exactement le s de tu au présent.","Les verbes et les contextes demandent une vérification ; le modèle en -er étudié n’a pas ce s.")],replacement={2:mcq("fi3-33-imperatif",2,"Donne l’impératif de « {v} » correspondant à « {fr2ImperPerson(k)} ».","{fr2Imperatif(v,k)}",[("{fr2Imperatif(v,(k+1)%3)}","personne"),("{v}","infinitif"),("{fr2ImperPerson(k)+' '+fr2Imperatif(v,k)}","sujet")],["Choisis la personne de la consigne.","L’impératif attendu est {answer}, sans pronom sujet."],vars={"v":{"pick":["travailler","parler","jouer","finir"]},"k":{"int":[0,2]}},misc=[("personne","Cette forme s’adresse à une autre personne ou à un autre groupe."),("infinitif","Tu as gardé l’infinitif au lieu de former l’impératif personnel demandé."),("sujet","Le modèle de l’impératif n’exprime pas ce pronom sujet avant le verbe.")],sources=["francais"],lang="fr")})

# S’exclamer uses the engine's existing regular -er rule. Keep the reflexive pronoun explicit;
# the verb is lexically pronominal, so no standalone non-pronominal usage is taught.
REFLEX=["m’","t’","s’","s’","nous ","vous ","s’","s’"]
unit(34,"Le présent d’un verbe essentiellement pronominal",
 "Un verbe pronominal se construit avec un pronom de même personne que le sujet. Un verbe essentiellement pronominal s’emploie ainsi dans le sens étudié : s’exclamer en est un exemple. Le pronom n’est pas facultatif. Au présent, on choisit à la fois la personne du verbe et le pronom correspondant. Devant une voyelle, me, te et se deviennent m’, t’ et s’. La leçon ne transforme pas ce verbe en voix passive ; cette autre formulation du spine reste en attente aux lignes concernées.",
 "Modèles calculés pour s’exclamer : {fr2With(0,'m’'+fr2Present('exclamer',0))} ; {fr2With(1,'t’'+fr2Present('exclamer',1))} ; {fr2With(4,'nous '+fr2Present('exclamer',4))} ; {fr2With(6,'s’'+fr2Present('exclamer',6))}. Le sujet et le pronom ont la même personne. Exclamer est utilisé comme base de calcul régulière, pas comme un verbe non pronominal proposé à l’élève.",
 "Repère le sujet, choisis le pronom réfléchi puis calcule la forme au présent. Vérifie l’élision et la terminaison. Ne confonds pas je m’exclame avec je lui parle : lui désigne alors une autre personne et ne rend pas le verbe pronominal.",[
 F("verbe essentiellement pronominal","un verbe construit avec son pronom dans le sens lexical étudié","S’exclamer est présenté avec son pronom dans ce sens.","Dans ce sens, le pronom de s’exclamer est toujours facultatif.","Le pronom appartient à la construction étudiée."),F("même personne","la correspondance du sujet et du pronom pronominal","Nous nous {fr2Present('exclamer',4)} conserve cette correspondance.","Nous s’exclament respecte la correspondance du modèle.","Nous exige nous et une forme verbale de nous."),F("élision du pronom","la réduction de me, te ou se devant la voyelle du verbe","{fr2With(0,'m’'+fr2Present('exclamer',0))} emploie m’.","Devant exclame, on doit écrire me exclame sans élision.","Me devient m’ devant la voyelle."),F("terminaison du présent","la finale du verbe liée à son sujet","Avec vous, on obtient {fr2With(5,'vous '+fr2Present('exclamer',5))}.","Vous vous exclament est la forme attendue.","Vous demande ici la terminaison -ez.")],replacement={2:mcq("fi3-34-pronominal",2,"Conjugue s’exclamer au présent avec « {fr2Pronoun(p)} ».","{fr2With(p,R[p]+fr2Present('exclamer',p))}",[("{fr2With(p,fr2Present('exclamer',p))}","oubli"),("{fr2With(p,R[(p+1)%8]+fr2Present('exclamer',p))}","pronom"),("{fr2With(p,R[p]+fr2Present('exclamer',(p+4)%8))}","verbe")],["Associe le sujet à son pronom et à la terminaison du présent.","La construction complète est {answer}."],vars={"p":{"pick":[0,1,4,5,6]},"R":REFLEX},where=["R[p] != R[(p+1)%8]","fr2Present('exclamer',p) != fr2Present('exclamer',(p+4)%8)"],misc=[("oubli","Il manque le pronom nécessaire à ce verbe essentiellement pronominal."),("pronom","Le pronom ne correspond pas à la personne du sujet."),("verbe","Le pronom convient, mais la terminaison verbale correspond à un autre sujet.")],sources=["francais"],lang="fr")})

writing(36,"Lire et remplir un modèle fictif de fiche de santé",
 "Une fiche de santé peut contenir une identité, une date, un motif et des observations rédigées par une personne compétente. Lire les rubriques aide à distinguer une observation et un diagnostic. Pour l’exercice scolaire, utilise un personnage fictif et aucune donnée médicale réelle. Ne coche pas au hasard une maladie ou un traitement pour remplir une case. La forme et les champs officiels varient ; le modèle ne remplace pas un document de soins.",
 "FICHE FICTIVE — EXERCICE DE FRANÇAIS. Personnage : Élève imaginaire A. Objet de l’exercice : comprendre les rubriques. Observation fictive : le personnage demande à être orienté vers un professionnel. Diagnostic et traitement : non fournis dans ce modèle scolaire. Aucun renseignement sur la santé d’un élève réel n’est demandé.",
 "Lis les intitulés et identifie qui est autorisé à compléter chaque partie. En cas d’information absente, écris non fourni pour le modèle au lieu d’inventer un diagnostic. Ne signe pas au nom d’un professionnel et ne partage pas de données réelles.",[
 F("identité fictive","un personnage inventé pour l’exercice","Élève imaginaire A évite une identité médicale réelle.","Une activité de français exige le dossier médical réel d’un camarade.","Le modèle doit rester fictif."),F("observation","un renseignement décrit sans conclure à lui seul à une maladie","Le modèle rapporte seulement une demande d’orientation.","Toute observation constitue automatiquement un diagnostic certain.","Observer et diagnostiquer sont deux opérations distinctes."),F("diagnostic professionnel","l’identification médicale relevant d’une personne compétente","La fiche scolaire laisse le diagnostic non fourni.","L’élève doit inventer un diagnostic pour que la fiche semble complète.","Il ne faut pas fabriquer une information médicale."),F("confidentialité","la protection des informations personnelles de santé","L’exercice ne demande aucune donnée réelle de santé.","Un dossier médical doit toujours être affiché à toute la classe.","Les informations privées doivent être protégées.")],
 "Dessine une fiche entièrement fictive destinée à comprendre les rubriques. Indique personnage imaginaire, objet scolaire et observation fictive ; laisse diagnostic et traitement non fournis. Ne saisis aucune information médicale réelle.",["Je distingue identité, observation et diagnostic.","Je n’invente ni traitement ni signature professionnelle.","Le modèle ne contient aucune donnée de santé réelle."])

vocab(37,"Le lexique du relief",
 "Le relief décrit les formes de la surface terrestre. Une montagne présente une élévation importante ; un plateau est une surface relativement plane en altitude ; une plaine présente peu de dénivelé à une altitude généralement plus basse ; une vallée forme un creux allongé entre des reliefs. Ces catégories sont des modèles descriptifs, pas des mesures absolues identiques partout. Un plateau n’est pas une plaine uniquement parce que son sommet est relativement plat.",
 "Une lecture scolaire de paysages camerounais peut distinguer une montagne, un plateau, une plaine et une vallée. Pour un croquis fictif, le lecteur observe la forme et la position plutôt que le seul mot haut ou plat. Il décrit les indices avant de choisir une catégorie.",[
 ("montagne","une élévation importante du terrain dans le modèle","Le croquis montre un relief élevé et marqué.","Une montagne est nécessairement une surface basse sans élévation.","La catégorie souligne une élévation importante."),("plateau","une surface relativement plane située en altitude","Le sommet étendu et relativement plat est élevé par rapport aux zones voisines.","Toute surface plane est obligatoirement une plaine basse.","La position élevée aide ici à distinguer le plateau."),("plaine","une étendue avec peu de dénivelé, généralement à plus basse altitude","Le croquis présente une zone basse et peu accidentée.","Une plaine exige toujours une pente extrêmement forte.","Le modèle souligne un faible dénivelé."),("vallée","un creux allongé entre des reliefs","Un espace bas et allongé sépare les versants.","Toute vallée est le sommet le plus élevé du paysage.","La vallée est ici un creux entre les reliefs.")])

unit(38,"L’accord des adjectifs de couleur",
 "Un adjectif de couleur simple comme bleu ou vert s’accorde généralement avec le nom. Certains noms employés comme couleurs, notamment orange et marron, restent invariables dans les modèles usuels. Rose est une exception qui s’accorde. Une couleur composée, comme bleu clair, reste généralement invariable. Ne décide pas à partir du seul nombre d’objets : vérifie la nature de l’expression de couleur et ses exceptions.",
 "Compare une robe {fr2Adj('bleu','f',false)}, des robes {fr2Adj('bleu','f',true)}, des tissus {fr2Adj('orange','m',true)} et des robes {fr2Adj('rose','f',true)}. La couleur composée bleu clair ne prend pas de marques dans des robes bleu clair. La ressemblance avec un nom de fruit ne fournit pas une règle sans exception.",
 "Identifie le nom, son genre et son nombre. Demande ensuite si la couleur est un adjectif simple variable, un nom de couleur invariable ou une expression composée. Vérifie notamment rose au lieu d’appliquer aveuglément la règle des noms employés comme couleurs.",[
 F("adjectif simple variable","une couleur simple recevant l’accord dans le modèle bleu","Des robes {fr2Adj('bleu','f',true)} portent féminin et pluriel.","Bleu reste toujours invariable même lorsqu’il est adjectif simple.","Bleu adjectif simple s’accorde ici avec robes."),F("nom de couleur invariable","le modèle illustré par orange et marron","Des tissus {fr2Adj('orange','m',true)} conservent orange.","Orange prend obligatoirement un s dans tous ses emplois de couleur.","Employé seul comme nom de couleur dans ce modèle, orange est invariable."),F("exception rose","un mot de couleur d’origine nominale qui s’accorde","Des robes {fr2Adj('rose','f',true)} prennent le pluriel.","Rose est nécessairement invariable comme orange.","Rose fait partie des exceptions qui s’accordent."),F("couleur composée","une expression de couleur généralement invariable comme bleu clair","Des robes bleu clair ne marquent pas le pluriel dans la couleur.","Bleu clair doit obligatoirement devenir bleues claires dans cet emploi.","La couleur composée reste invariable dans ce modèle.")],replacement={2:mcq("fi3-38-couleur",2,"Accorde la couleur simple « {a} » au {fr2GenderNumber(g,pl)}.","{fr2Adj(a,g,pl)}",[("{fr2Adj(a,fr2OtherGender(g),pl)}","genre"),("{fr2Adj(a,g,!pl)}","nombre"),("{fr2Adj(a,fr2OtherGender(g),!pl)}","deux")],["Il s’agit d’un adjectif de couleur simple variable.","La forme attendue est {answer}."],vars={"a":{"pick":["bleu","vert","blanc","noir"]},"g":{"pick":["m","f"]},"pl":{"pick":[True,False]}},misc=[("genre","Cette couleur ne porte pas le genre demandé."),("nombre","Cette couleur ne porte pas le nombre demandé."),("deux","Cette forme change à la fois le genre et le nombre.")],sources=["francais"],lang="fr")})

vocab(43,"Le lexique de la végétation",
 "La végétation est l’ensemble des plantes présentes dans un milieu. Une forêt comporte une couverture d’arbres importante ; une savane associe une couverture herbacée à des arbres ou arbustes plus ou moins dispersés ; un arbuste est une plante ligneuse généralement de taille inférieure à un arbre ; une herbe a des tiges non ligneuses dans le modèle introductif. Les milieux varient et leurs limites ne se déduisent pas d’une photo d’un seul arbre.",
 "Un passage original compare un couvert forestier, une étendue herbacée avec des arbres dispersés et un jardin où poussent de petits arbustes. Le lecteur distingue la formation végétale de la plante individuelle. Les mots ne prouvent pas à eux seuls la région exacte, la saison ou l’état de conservation d’un lieu.",[
 ("forêt","une formation comportant une couverture importante d’arbres","Le passage décrit un couvert arboré important.","Un arbre isolé prouve nécessairement l’existence d’une forêt complète.","Une formation se décrit à une échelle plus large qu’un arbre isolé."),("savane","une formation à couverture herbacée avec des ligneux dispersés selon le milieu","Une étendue herbacée porte des arbres dispersés dans le modèle.","Toute savane est nécessairement sans aucune plante herbacée.","La couverture herbacée est importante dans ce modèle."),("arbuste","une plante ligneuse généralement plus petite qu’un arbre","Le jardin comporte un petit végétal à tiges ligneuses.","Un arbuste n’a jamais de partie ligneuse.","Le caractère ligneux aide ici à le distinguer d’une herbe."),("herbe","une plante à tiges non ligneuses dans le modèle introductif","Le texte distingue les tiges souples non ligneuses du bois.","Herbe est obligatoirement le nom de tout grand arbre.","La catégorie ne se confond pas avec un arbre ligneux.")])

unit(44,"Les déterminants interrogatifs quel, quelle, quels et quelles",
 "Quel, quelle, quels et quelles accompagnent un nom dans une question et s’accordent avec lui. La tradition scolaire les appelle souvent adjectifs interrogatifs ; la grammaire actuelle parle de déterminants interrogatifs. Le genre vient du nom et le nombre de la situation décrite. Ne les confonds pas avec qu’elle, contraction de que et elle dans une autre construction. La prononciation seule ne suffit pas à choisir la graphie.",
 "Quel livre ? Quelle activité ? Quels livres ? Quelles activités ? Ces groupes portent les marques du nom qu’ils introduisent. Le choix ne dépend pas du genre de la personne qui pose la question. Une élève peut demander quel livre, car livre reste masculin.",
 "Repère le nom, trouve son genre et son nombre puis choisis la forme correspondante. Si tu vois qu’elle, vérifie s’il s’agit au contraire de que suivi du pronom elle. Dans l’exercice, les noms sont donnés pour rendre le choix explicite.",[
 F("quel","la forme interrogative masculine singulière","Quel livre accompagne livre au singulier.","Quel doit prendre un e parce que la personne qui questionne est une fille.","L’accord dépend du nom livre, pas du locuteur."),F("quelle","la forme interrogative féminine singulière","Quelle activité accompagne activité au singulier.","Quelle est obligatoirement masculin pluriel.","Cette forme est féminin singulier."),F("quels","la forme interrogative masculine plurielle","Quels livres accompagne livres au pluriel.","Quels ne peut accompagner qu’un nom féminin singulier.","La forme marque masculin et pluriel."),F("quelles","la forme interrogative féminine plurielle","Quelles activités accompagne activités au pluriel.","Quelles signifie toujours que suivi du pronom elles.","Ici c’est un déterminant interrogatif accordé avec activités.")],replacement={2:B.QA("fi3-44-accord",2,"{X.q}",[
 dict(q="Complète : ___ livre choisis-tu ?",r="Quel",w=["Quelle","Quels","Quelles"],e=["Livre est masculin, pas féminin.","Livre est singulier ici.","Cette forme change genre et nombre."],y="Livre est masculin singulier."),
 dict(q="Complète : ___ activité choisis-tu ?",r="Quelle",w=["Quel","Quels","Quelles"],e=["Activité est féminin.","Cette forme change genre et nombre.","Activité est singulier ici."],y="Activité est féminin singulier."),
 dict(q="Complète : ___ livres choisis-tu ?",r="Quels",w=["Quel","Quelle","Quelles"],e=["Livres est pluriel.","Cette forme change genre et nombre.","Livres est masculin."],y="Livres est masculin pluriel."),
 dict(q="Complète : ___ activités choisis-tu ?",r="Quelles",w=["Quel","Quelle","Quels"],e=["Cette forme change genre et nombre.","Activités est pluriel.","Activités est féminin."],y="Activités est féminin pluriel.")],["francais"])})

vocab(47,"Le lexique de la gestion des déchets",
 "La gestion des déchets comprend la réduction à la source, la collecte, le tri et des traitements appropriés. Collecter signifie rassembler pour une prise en charge ; trier sépare selon des catégories ; recycler transforme une matière par une filière adaptée ; un déchet dangereux nécessite des précautions particulières. Le tri seul ne garantit pas un recyclage effectif. Les élèves doivent suivre les consignes locales et ne pas manipuler d’objets coupants, médicaux ou inconnus.",
 "Dans un projet fictif, un club lit les consignes de l’école avant d’agir. Il distingue le rassemblement des papiers autorisés, leur séparation selon les catégories acceptées et le traitement par une filière. Il confie au personnel compétent le signalement d’un objet dangereux au lieu de le toucher pour une démonstration.",[
 ("collecte","le rassemblement de déchets pour leur prise en charge","Des papiers autorisés sont réunis au point prévu.","Collecter signifie nécessairement transformer industriellement toute matière.","La collecte rassemble ; le traitement est une autre étape."),("tri","la séparation des déchets selon des catégories pertinentes","Les matières sont séparées selon les consignes acceptées localement.","Un objet trié est automatiquement déjà recyclé.","La séparation ne prouve pas le traitement effectif."),("recyclage","la transformation d’une matière par une filière adaptée","Une filière transforme une matière acceptée.","Tout objet se recycle de la même manière partout.","Les matières acceptées et les installations varient."),("déchet dangereux","un déchet demandant des précautions spécifiques","Un objet coupant inconnu est signalé sans être manipulé par les élèves.","Un déchet médical inconnu doit être touché à mains nues pour apprendre.","Signale l’objet et respecte les consignes du personnel compétent.")])

